/* Hushfield granular synthesis processor. */
class GrainEngine extends AudioWorkletProcessor {
  constructor(){super();this.channels=[];this.sourceRate=48000;this.grains=[];this.p={};this.playing=false;this.scan=.5;this.clock=0;this.untilGrain=0;this.direction=1;this.lastPosition=.5;this.smoothedPosition=.5;this.frameCounter=0;this.port.onmessage=({data:m})=>{if(m.type==='sample'){this.channels=m.channels;this.sourceRate=m.sampleRate;this.grains=[];this.scan=m.position??.5;this.untilGrain=0;this.smoothedPosition=this.scan;}if(m.type==='params'){const old=this.p;this.p={...old,...m.params};if(m.params.position!==undefined&&m.params.position!==old.position)this.scan=m.params.position;}if(m.type==='play'){this.playing=m.value;if(!m.value)this.grains=[];this.untilGrain=0;}};}
  spawn(){const p=this.p,len=this.channels[0]?.length;if(!len||this.grains.length>=160)return;if(Math.random()*100<(p.hold||0))return;let pos=this.scan; if(Math.random()*100<(p.static||0))pos=this.lastPosition;if(Math.random()*100<(p.jump||0))pos=Math.random();pos+=(Math.random()-.5)*((p.spray||0)/100)+Math.sin(this.clock*.31)*(p.wander||0)/400;pos=((pos%1)+1)%1;const smoothing=(p.smooth||0)/100;this.smoothedPosition+=(pos-this.smoothedPosition)*Math.max(.015,1-smoothing*.985);pos=this.smoothedPosition;this.lastPosition=pos;
    const chaos=(p.chaos||0)/100;const duration=Math.max(.012,(p.size||200)/1000*(1+(Math.random()-.5)*chaos));const rev=Math.random()*100<(p.reverse||0)?-1:1;const pitch=(p.pitch||0)+(Math.random()-.5)*(p.elastic||0)/12;const rate=2**(pitch/12)*this.sourceRate/sampleRate*rev;
    const width=(p.width??65)/100;this.grains.push({position:pos*len,age:0,duration:Math.floor(duration*sampleRate),rate,pan:(Math.random()*2-1)*width,amplitude:Math.min(.8,1.1/Math.sqrt(Math.max(1,(p.density||12)*duration)))});
  }
  process(inputs,outputs){const out=outputs[0];if(!out?.length)return true;const p=this.p,len=this.channels[0]?.length||0;let peak=0;for(let i=0;i<out[0].length;i++){let l=0,r=0;if(this.playing&&len){if(this.untilGrain<=0){this.spawn();const jitter=1+(Math.random()-.5)*(p.chaos||0)/100;this.untilGrain=sampleRate/Math.max(1,p.density||12)*jitter;}this.untilGrain--;if(p.scanOn&&!p.freeze){let speed=(p.speed??1)*this.direction;if(p.scanMode==='reverse')speed=-Math.abs(speed);const range=(p.range??100)/100,center=p.position??.5,lo=Math.max(0,center-range/2),hi=Math.min(1,center+range/2);this.scan+=speed/(len/this.sourceRate)/sampleRate;if(this.scan>hi){this.scan=hi;if(p.scanMode==='pingpong')this.direction=-1;else this.scan=lo;}if(this.scan<lo){this.scan=lo;if(p.scanMode==='pingpong')this.direction=1;else this.scan=hi;}}for(let g=this.grains.length-1;g>=0;g--){const grain=this.grains[g];if(grain.age>=grain.duration){this.grains.splice(g,1);continue;}const pos=((grain.position%len)+len)%len,idx=Math.floor(pos),f=pos-idx;const a=this.channels[0],b=this.channels[1]||a;const env=Math.sin(Math.PI*grain.age/grain.duration)**2;const left=a[idx]*(1-f)+a[(idx+1)%len]*f;const right=b[idx]*(1-f)+b[(idx+1)%len]*f;l+=left*env*grain.amplitude*Math.sqrt((1-grain.pan)/2);r+=right*env*grain.amplitude*Math.sqrt((1+grain.pan)/2);grain.age++;grain.position+=grain.rate;}}out[0][i]=l;if(out[1])out[1][i]=r;peak=Math.max(peak,Math.abs(l),Math.abs(r));this.clock+=1/sampleRate;}this.frameCounter+=out[0].length;if(this.frameCounter>=sampleRate/15){this.port.postMessage({scan:this.scan,count:this.grains.length,peak,grains:this.grains.slice(-45).map(g=>({position:((g.position%Math.max(1,len))+len)%Math.max(1,len)/Math.max(1,len),life:g.age/g.duration}))});this.frameCounter=0;}return true;}
}
registerProcessor('grain-engine',GrainEngine);

// Capture post-effects PCM in the audio thread so exports are portable WAV files.
class CaptureEngine extends AudioWorkletProcessor {
  constructor(){super();this.recording=false;this.left=new Float32Array(4096);this.right=new Float32Array(4096);this.offset=0;this.port.onmessage=({data})=>{if(data.type==='start'){this.offset=0;this.recording=true;}if(data.type==='stop'){this.recording=false;this.flush();this.port.postMessage({type:'done'});}};}
  flush(){if(!this.offset)return;this.port.postMessage({type:'chunk',left:this.left.slice(0,this.offset),right:this.right.slice(0,this.offset)});this.offset=0;}
  process(inputs){const input=inputs[0];if(this.recording&&input?.[0]){const l=input[0],r=input[1]||l;for(let i=0;i<l.length;i++){this.left[this.offset]=l[i];this.right[this.offset]=r[i];this.offset++;if(this.offset===4096)this.flush();}}return true;}
}
registerProcessor('capture-engine',CaptureEngine);
